33	
34	    /**
35	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
36	     * last names, as required by the API's read-only {@code displayName} field.
37	     *
38	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
39	     * applied only where referenced via {@code qualifiedByName}.
40	     */
41	    @Named("formatDisplayName")
42	    default String formatDisplayName(Owner owner) {
43	        if (owner == null) {
44	            return null;
45	        }
46	        return owner.getLastName() + ", " + owner.getFirstName();
47	    }
48	
49	    /**
50	     * Formats an owner's initials as the upper-cased first letters of the first and last
51	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
52	     * API's read-only {@code initials} field.
53	     *
54	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
55	     * applied only where referenced via {@code qualifiedByName}.
56	     */
57	    @Named("formatInitials")
58	    default String formatInitials(Owner owner) {
59	        if (owner == null) {
60	            return null;
61	        }
62	        return initial(owner.getFirstName()) + initial(owner.getLastName());
63	    }
64	
65	    /**
66	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
67	     * {@code customerCode} is the owner's customer code and {@code YY} is the last two
68	     * digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}), as required
69	     * by the API's read-only {@code membershipNumber} field. Returns {@code null} when
70	     * either the customer code or registration date is absent.
71	     *
72	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
73	     * applied only where referenced via {@code qualifiedByName}.
74	     */
75	    @Named("formatMembershipNumber")
76	    default String formatMembershipNumber(Owner owner) {
77	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
78	            return null;
79	        }
80	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
81	    }
82	
83	    /**
84	     * Derives an owner's membership level, as required by the API's read-only
85	     * {@code membershipLevel} field: starting at 1, plus 1 when an email address is present,
86	     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), capped at 3. (Level 4
87	     * is reserved for tenure.)
88	     *
89	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
90	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
91	     * to record the membership level on the create audit line).
92	     */
93	    @Named("formatMembershipLevel")
94	    default Integer formatMembershipLevel(Owner owner) {
95	        if (owner == null) {
96	            return null;
97	        }
98	        int level = 1;
99	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
100	            level++;
101	        }
102	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
103	            level++;
104	        }
105	        return Math.min(level, 3);
106	    }
107	
108	    /**
109	     * Derives an owner's locality, as required by the API's read-only {@code locality}
110	     * field: the canonical region from the fixed city-to-region table
111	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
112	     * {@code 'UNKNOWN'} when the city is not in the table.
113	     *
114	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
115	     * applied only where referenced via {@code qualifiedByName}.
116	     */
117	    @Named("formatLocality")
118	    default String formatLocality(Owner owner) {
119	        if (owner == null) {
120	            return null;
121	        }
122	        return LocalityResolver.resolve(owner.getCity());
123	    }
124	
125	    private static String initial(String name) {
126	        if (name == null || name.isEmpty()) {
127	            return "";
128	        }
129	        return Character.toUpperCase(name.charAt(0)) + ".";
130	    }
131	
132	    Owner toOwner(OwnerDto ownerDto);
133	
134	    @Mapping(target = "id", ignore = true)
135	    @Mapping(target = "pets", ignore = true)
136	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
137	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
138	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
139	    Owner toOwner(OwnerFieldsDto ownerDto);
140	
141	    /**
142	     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
143	     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
144	     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
145	     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
146	     * {@code '12 MAIN STREET'}.
147	     *
148	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
149	     * only where referenced via {@code qualifiedByName}.
150	     */
151	    @Named("normalizeAddress")
152	    default String normalizeAddress(String address) {
153	        return AddressNormalizer.normalize(address);
154	    }
155	
156	    /**
